      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "याञ्चाभङ्गभयेन गद्गदगलत्त्रुट्यद्विलीनाक्षरं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "को देहीति वदेत्स्वदग्धजठरस्यार्थे मनस्वी जनः ॥ ८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "निवृत्ता भोगेच्छा पुरुषबहुमानो विगलितः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "समानाः स्वर्याताः सपदि सुहृदो जीवितसमाः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "शनैर्यष्ट्युत्थानं घनतिमिररुद्धे च नयने",
          "end": "line"
        },
        {
          "n": 4,
          "text": "अहो धृष्टः कायस्तदपि मरणापायचकितः ॥ ९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "हिंसाशून्यमयत्नलभ्यमशनं धात्रा मरुत्कल्पितं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "व्यालानां पशवस्तृणाङ्कुरभुजः सृष्टाः स्थलीशायिनः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "संसारार्णवलङ्घनक्षमधियां वृत्तिः कृता सा नृणां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "यामन्वेषयतां प्रयान्ति सततं सर्वे समाप्तिं गुणाः ॥ १० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "न ध्यातं पदमीश्वरस्य विधिवत्संसारविच्छित्तये",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स्वर्गद्वारकपाटपाटनपटुर्धर्मोपि नोपार्जितः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "नारीपीनपयोधरोरुयुगुलं स्वप्नेपि नालिङ्गितं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "मातुः केवलमेव यौवनवनच्छेदे कुठारा वयम् ॥ ११ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
